namespace HeartbeatDesktop {
 static class Program {
  public static readonly string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Heartbeat");
  public static readonly string Active=Path.Combine(Root,"active-artwork.json");
  public static readonly string Applied=Path.Combine(Root,"applied-artwork.json");
  public static string Field(Dictionary<string,object> data,string key){object value;return data!=null&&data.TryGetValue(key,out value)&&value!=null?Convert.ToString(value):"";}
  public static Dictionary<string,object> Manifest(string filename){try{if(!File.Exists(filename)||new FileInfo(filename).Length>32768)return null;var d=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(filename));string origin=Field(d,"origin"),owner=Field(d,"accountId"),surface=Field(d,"surfaceId"),id=Field(d,"assetId");Guid parsed;if(!AllowedServer(origin)||owner.Length==0||owner.Length>100||surface.Length==0||surface.Length>100||!Guid.TryParse(id,out parsed))return null;string expected=Path.GetFullPath(Path.Combine(Root,"cache",Namespace(origin,owner,surface),id+".jpg"));return String.Equals(expected,Path.GetFullPath(Field(d,"path")),StringComparison.OrdinalIgnoreCase)?d:null;}catch{return null;}}
  public static string Cache {get{var d=Manifest(Active);return d!=null?Field(d,"path"):Path.Combine(Root,"unpaired.jpg");}}
  public static void ClearCache(){if(File.Exists(Active))File.Delete(Active);}
  public static void AtomicText(string path,string text){string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";File.WriteAllText(temp,text);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
  public static double UtcMilliseconds(){return (DateTime.UtcNow-new DateTime(1970,1,1)).TotalMilliseconds;}
  public static bool NightRequired(Dictionary<string,object> manifest,double current){try{var p=(Dictionary<string,object>)manifest["policy"];double evaluated=Convert.ToDouble(p["evaluatedAt"]),until=Convert.ToDouble(p["safeDayUntil"]);return Convert.ToInt32(p["version"])!=1||String.IsNullOrWhiteSpace(Field(p,"timezone"))||!(p["night"] is bool)||Convert.ToBoolean(p["night"])||Double.IsNaN(evaluated)||Double.IsInfinity(evaluated)||Double.IsNaN(until)||Double.IsInfinity(until)||current<evaluated-300000||current>=evaluated+900000||until>evaluated+900000||current>=until;}catch{return true;}}
  public static bool NightRequired(){return NightRequired(Manifest(Active),UtcMilliseconds());}
  public static string SafeFallback(){Directory.CreateDirectory(Root);string file=Path.Combine(Root,"safe-night.bmp");if(!File.Exists(file)){using(var b=new Bitmap(512,512)){using(var g=Graphics.FromImage(b))g.Clear(Color.FromArgb(3,8,14));b.Save(file,System.Drawing.Imaging.ImageFormat.Bmp);}}return file;}
  public static void PurgeCache(){var manifest=Manifest(Active);ClearCache();if(File.Exists(Applied))File.Delete(Applied);if(manifest!=null){string folder=Path.GetDirectoryName(Field(manifest,"path")),allowed=Path.GetFullPath(Path.Combine(Root,"cache"))+Path.DirectorySeparatorChar;if(Directory.Exists(folder)&&Path.GetFullPath(folder).StartsWith(allowed,StringComparison.OrdinalIgnoreCase)&&(File.GetAttributes(folder)&FileAttributes.ReparsePoint)==0){foreach(string file in Directory.GetFiles(folder)){if((File.GetAttributes(file)&FileAttributes.ReparsePoint)==0)File.Delete(file);}if(Directory.GetDirectories(folder).Length==0)Directory.Delete(folder);}}string old=Path.Combine(Root,"latest.jpg");if(File.Exists(old))File.Delete(old);}
  public static async Task<bool> Acknowledge(Dictionary<string,object> manifest){try{if(manifest==null)return false;string config=Path.Combine(Root,"device.json");if(!File.Exists(config)||new FileInfo(config).Length>16000)return false;var saved=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(config));string origin=Field(saved,"origin");if(!AllowedServer(origin)||origin!=Field(manifest,"origin")||Field(saved,"accountId")!=Field(manifest,"accountId")||Field(saved,"surfaceId")!=Field(manifest,"surfaceId"))return false;string token=Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(Field(saved,"token")),null,DataProtectionScope.CurrentUser));using(var handler=new HttpClientHandler{AllowAutoRedirect=false})using(var http=new HttpClient(handler){Timeout=TimeSpan.FromSeconds(10)})using(var request=new HttpRequestMessage(HttpMethod.Post,origin+"/api/product/device/display")){request.Headers.Add("Origin",origin);request.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",token);var policy=(Dictionary<string,object>)manifest["policy"];request.Content=new StringContent(Json.Serialize(new Dictionary<string,object>{{"id",Field(manifest,"assetId")},{"surfaceId",Field(manifest,"surfaceId")},{"eventId","desktop:"+Field(manifest,"surfaceId")+":"+Field(manifest,"assetId")},{"presentationPolicyVersion",policy["version"]}}),Encoding.UTF8,"application/json");using(var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead)){if(response.StatusCode==HttpStatusCode.Unauthorized)ClearCache();return response.IsSuccessStatusCode;}}}catch{return false;}}
  public static string Namespace(string origin,string owner,string surface){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(origin+"|"+owner+"|"+surface))).Replace("-","").ToLowerInvariant();}
  public static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
  public static bool AllowedServer(string text) {Uri uri;return Uri.TryCreate(text,UriKind.Absolute,out uri)&&uri.UserInfo==""&&uri.AbsolutePath=="/"&&uri.Query==""&&uri.Fragment==""&&(uri.Scheme=="https"||uri.Scheme=="http"&&uri.IsLoopback);}
  public static string Mode(string[] args) {if(args.Length==0)return "config";string a=args[0].ToLowerInvariant();if(a=="--self-test")return "test";if(a=="/s"||a=="-s")return "screen";if(a.StartsWith("/p")||a.StartsWith("-p"))return "preview";return "config";}
  public static IntPtr PreviewHandle(string[] args) {if(args.Length==0)return IntPtr.Zero;string[] parts=args[0].Split(':');string raw=parts.Length>1?parts[1]:args.Length>1?args[1]:"";long value;return long.TryParse(raw,out value)&&value>0?new IntPtr(value):IntPtr.Zero;}
  public static bool NightSafe(Bitmap bitmap){return NightSafe(bitmap,16.0/9);}
  public static bool NightSafe(Bitmap bitmap,double aspect){double sum=0;int bright=0;double width=bitmap.Width,height=bitmap.Height;if(width/height>aspect)width=height*aspect;else height=width/aspect;for(int y=0;y<20;y++)for(int x=0;x<32;x++){int px=Math.Min(bitmap.Width-1,(int)((bitmap.Width-width)/2+(x+.5)*width/32)),py=Math.Min(bitmap.Height-1,(int)((bitmap.Height-height)/2+(y+.5)*height/20));Color c=bitmap.GetPixel(px,py);double light=(.2126*c.R+.7152*c.G+.0722*c.B)/255;sum+=light;if(light>.8)bright++;}return sum/640<=.32&&bright/640.0<=.12;}
  public static Bitmap ReadPicture(string path) {if(new FileInfo(path).Length>12000000)throw new Exception("Picture is too large.");using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){using(var source=Image.FromStream(stream,true,true)){if(source.Width<512||source.Height<512||source.Width>4096||source.Height>4096)throw new Exception("Picture dimensions are invalid.");return new Bitmap(source);}}}
  [STAThread] static int Main(string[] args) {
   if(Mode(args)=="test") {try{SelfTest();Console.WriteLine("Heartbeat desktop self-tests passed. No settings changed.");return 0;}catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
   ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Directory.CreateDirectory(Root);
   if(Mode(args)=="screen"){var forms=new List<Saver>();foreach(var screen in Screen.AllScreens)forms.Add(new Saver(screen.Bounds,IntPtr.Zero));foreach(var form in forms)form.FormClosed+=(s,e)=>{foreach(var f in forms)if(!f.IsDisposed)f.Close();Application.ExitThread();};foreach(var form in forms)form.Show();Application.Run();}
   else if(Mode(args)=="preview"){IntPtr parent=PreviewHandle(args);if(parent!=IntPtr.Zero)Application.Run(new Saver(Rectangle.Empty,parent));}
   else Application.Run(new Companion());return 0;
  }
  static void SelfTest() {
   if(!AllowedServer("https://heartbeat.example")||!AllowedServer("http://localhost:5173")||!AllowedServer("http://127.0.0.1:5173")||AllowedServer("http://heartbeat.example")||AllowedServer("https://user:password@example.com")||AllowedServer("https://example.com/steal"))throw new Exception("Origin validation failed");
   if(Mode(new[]{"/s"})!="screen"||Mode(new[]{"/c"})!="config"||Mode(new[]{"/p:123"})!="preview"||PreviewHandle(new[]{"/p","123"}).ToInt64()!=123||PreviewHandle(new[]{"/p:bad"})!=IntPtr.Zero)throw new Exception("Screensaver arguments failed");
   using(var black=new Bitmap(64,64)){using(var g=Graphics.FromImage(black))g.Clear(Color.Black);if(!NightSafe(black))throw new Exception("Dark guard failed");using(var g=Graphics.FromImage(black))g.Clear(Color.White);if(NightSafe(black))throw new Exception("Bright guard failed");}
   if(Program.Namespace("https://one.example","alice","screen")==Program.Namespace("https://one.example","bob","screen"))throw new Exception("Cache namespace isolation failed");
   double at=1800000000000;var policy=new Dictionary<string,object>{{"version",1},{"timezone","Europe/London"},{"night",false},{"evaluatedAt",at},{"safeDayUntil",at+900000}};var manifest=new Dictionary<string,object>{{"policy",policy}};if(NightRequired(manifest,at)||!NightRequired(manifest,at+900000)||!NightRequired(manifest,at-300001))throw new Exception("Policy freshness failed");policy["version"]=2;if(!NightRequired(manifest,at))throw new Exception("Unknown presentation policy must fail safe");policy["version"]=1;policy["night"]=true;if(!NightRequired(manifest,at))throw new Exception("Selected-city night policy failed");
   policy["night"]=false;policy["safeDayUntil"]=at+86400000;if(!NightRequired(manifest,at))throw new Exception("An overly long offline daylight lease must fail safe");policy["safeDayUntil"]=Double.PositiveInfinity;if(!NightRequired(manifest,at)||!NightRequired(null,at))throw new Exception("Malformed presentation policy must fail safe");
   using(var cropped=new Bitmap(320,320)){using(var g=Graphics.FromImage(cropped)){g.Clear(Color.Black);g.FillRectangle(Brushes.White,0,80,320,160);}if(NightSafe(cropped,16.0/9)||NightSafe(cropped,9.0/16))throw new Exception("Rendered crop brightness guard failed");}
   byte[] plain=Encoding.UTF8.GetBytes("test-only-device-token"),encrypted=ProtectedData.Protect(plain,null,DataProtectionScope.CurrentUser);if(Encoding.UTF8.GetString(ProtectedData.Unprotect(encrypted,null,DataProtectionScope.CurrentUser))!="test-only-device-token")throw new Exception("DPAPI roundtrip failed");
  }
 }
