  }
  Button Button(string text,Func<Task> action) {var b=new Button{Text=text,AutoSize=false,Width=490,Height=38,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(37,56,42),ForeColor=ForeColor,Margin=new Padding(0,7,0,0)};b.Click+=async(s,e)=>await Work(action);return b;}
  async Task Work(Func<Task> action){if(busy)return;busy=true;try{state.Text="One quiet moment...";await action();}catch(Exception e){state.Text=e.Message;}finally{busy=false;}}
  static string Get(Dictionary<string,object> data,string key){object value;return data.TryGetValue(key,out value)&&value!=null?Convert.ToString(value):"";}
  async Task<Dictionary<string,object>> Call(string path,bool post,bool authorized,object payload=null){if(!Program.AllowedServer(origin))throw new Exception("Choose a valid application address.");if(authorized&&token=="")throw new Exception("Pair this desktop first.");using(var request=new HttpRequestMessage(post?HttpMethod.Post:HttpMethod.Get,origin+"/api/product/"+path)){request.Headers.Add("Origin",origin);if(authorized)request.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",token);if(post)request.Content=new StringContent(payload==null?"{}":Program.Json.Serialize(payload),Encoding.UTF8,"application/json");using(var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead)){string body;using(var stream=await response.Content.ReadAsStreamAsync())using(var memory=new MemoryStream()){byte[] buffer=new byte[8192];int read;while((read=await stream.ReadAsync(buffer,0,buffer.Length))>0){if(memory.Length+read>65536)throw new Exception("Application response was too large.");memory.Write(buffer,0,read);}body=Encoding.UTF8.GetString(memory.ToArray());}if(response.StatusCode==HttpStatusCode.Unauthorized){SafetyCheck(true);Program.PurgeCache();token="";lastId="";accountId="";surfaceId="";Save();}Dictionary<string,object> data;try{data=Program.Json.Deserialize<Dictionary<string,object>>(body);}catch{throw new Exception("The application returned an unreadable response.");}if(!response.IsSuccessStatusCode)throw new Exception(Get(data,"error")!=""?Get(data,"error"):Get(data,"reason")!=""?Get(data,"reason"):"The application is unavailable.");return data;}}}
  async Task Download(){
   SafetyCheck(false);var d=await Call("device/status",false,true);if(Get(d,"paired").ToLowerInvariant()!="true")throw new Exception("Approve the pairing code in your studio first.");object raw;var p=d.TryGetValue("picture",out raw)?raw as Dictionary<string,object>:null;if(p==null)throw new Exception("No original picture yet. Prepare one in your studio first.");string id=Get(p,"id");Guid guid;if(!Guid.TryParse(id,out guid))throw new Exception("Invalid picture reference.");object policyRaw;var policy=d.TryGetValue("policy",out policyRaw)?policyRaw as Dictionary<string,object>:null;if(policy==null)throw new Exception("Update the server to provide a presentation policy.");
   accountId=Get(d,"accountId");surfaceId=Get(d,"surfaceId");if(accountId.Length==0||accountId.Length>100||surfaceId.Length==0||surfaceId.Length>100)throw new Exception("Invalid display owner.");
   string folder=Path.Combine(Program.Root,"cache",Program.Namespace(origin,accountId,surfaceId));Directory.CreateDirectory(folder);string destination=Path.Combine(folder,id+".jpg");var manifest=new Dictionary<string,object>{{"version",1},{"origin",origin},{"accountId",accountId},{"surfaceId",surfaceId},{"path",destination},{"policy",policy},{"assetId",id}};
   if(File.Exists(destination)){using(var image=Program.ReadPicture(destination)){}Activate(manifest,id);state.Text="Your current picture is already cached.";return;}
   using(var request=new HttpRequestMessage(HttpMethod.Get,origin+"/api/product/device/art/"+id)){request.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",token);using(var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead)){
    if(response.StatusCode==HttpStatusCode.Unauthorized){SafetyCheck(true);Program.PurgeCache();token="";Save();throw new Exception("Pairing was revoked. Connect this display again.");}
    if(!response.IsSuccessStatusCode||response.Content.Headers.ContentType==null||response.Content.Headers.ContentType.MediaType!="image/jpeg")throw new Exception("Private picture could not be retrieved.");
    string temp=Path.Combine(folder,Guid.NewGuid().ToString("N")+".tmp");try{using(var source=await response.Content.ReadAsStreamAsync())using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write)){byte[] bytes=new byte[32768];int n,total=0;while((n=await source.ReadAsync(bytes,0,bytes.Length))>0){total+=n;if(total>12000000)throw new Exception("Picture is too large.");await output.WriteAsync(bytes,0,n);}}using(var picture=Program.ReadPicture(temp)){if(Get(p,"phase")=="night")foreach(var screen in Screen.AllScreens)if(!Program.NightSafe(picture,screen.Bounds.Width/(double)screen.Bounds.Height))throw new Exception("Night picture was too bright for this display.");}if(!File.Exists(destination))File.Move(temp,destination);Activate(manifest,id);state.Text="Cached: "+Get(p,"title")+". Apply it when ready.";}finally{if(File.Exists(temp))File.Delete(temp);}
   }}
  }
  void Activate(Dictionary<string,object> manifest,string id){Program.AtomicText(Program.Active,Program.Json.Serialize(manifest));lastId=id;Save();if(appliedManifest!=null&&Get(appliedManifest,"assetId")==id&&Get(appliedManifest,"origin")==origin&&Get(appliedManifest,"accountId")==accountId&&Get(appliedManifest,"surfaceId")==surfaceId){appliedManifest["policy"]=manifest["policy"];Program.AtomicText(Program.Applied,Program.Json.Serialize(appliedManifest));}nightValidated=false;SafetyCheck(false);}
  void Save(){Directory.CreateDirectory(Program.Root);string protectedToken=Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(token),null,DataProtectionScope.CurrentUser));Program.AtomicText(config,Program.Json.Serialize(new Dictionary<string,object>{{"origin",origin},{"token",protectedToken},{"accountId",accountId},{"surfaceId",surfaceId}}));}
  void LoadConfig(){try{if(!File.Exists(config)||new FileInfo(config).Length>16000)return;var d=Program.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(config));string value=Get(d,"origin");if(!Program.AllowedServer(value))return;origin=value;server.Text=origin;accountId=Get(d,"accountId");surfaceId=Get(d,"surfaceId");token=Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(Get(d,"token")),null,DataProtectionScope.CurrentUser));pairing.Text="A previous pairing is saved for this Windows account.";}catch{Program.ClearCache();state.Text="Saved pairing could not be opened. Request a new code.";}}
  void Apply(){
   var manifest=Program.Manifest(Program.Active);if(manifest==null||Get(manifest,"origin")!=origin||Get(manifest,"accountId")!=accountId||Get(manifest,"surfaceId")!=surfaceId||!File.Exists(Get(manifest,"path")))throw new Exception("Download a picture for this paired display first.");
   string original=Get(manifest,"path"),applyPath=original;var desktop=(IDesktopWallpaper)new DesktopWallpaper();try{
    uint count;desktop.GetMonitorDevicePathCount(out count);if(monitor.SelectedIndex>count)throw new Exception("The selected monitor changed. Reopen the companion.");
    var previous=new Dictionary<string,object>();var targets=new List<string>();uint position;desktop.GetPosition(out position);previous["position"]=position;
    using(var image=Program.ReadPicture(original)){for(uint i=0;i<count;i++){string path,wallpaper;desktop.GetMonitorDevicePathAt(i,out path);desktop.GetWallpaper(path,out wallpaper);previous[path]=wallpaper;if(monitor.SelectedIndex==0||monitor.SelectedIndex==i+1){targets.Add(path);NativeRect rectangle;desktop.GetMonitorRECT(path,out rectangle);if(Program.NightRequired(manifest,Program.UtcMilliseconds())&&!Program.NightSafe(image,Math.Max(1,rectangle.Right-rectangle.Left)/(double)Math.Max(1,rectangle.Bottom-rectangle.Top)))applyPath=Program.SafeFallback();}}}
