   }finally{Marshal.ReleaseComObject(desktop);}
  }
  void SafetyCheck(bool force){
   if(!applied||appliedManifest==null)return;force=force||Program.Manifest(Program.Active)==null;string layout=String.Join("|",Array.ConvertAll(Screen.AllScreens,s=>s.Bounds.ToString()));if(layout!=lastLayout){nightValidated=false;lastLayout=layout;}
   if(!force&&(!Program.NightRequired(appliedManifest,Program.UtcMilliseconds())||nightValidated&&File.Exists(Get(appliedManifest,"path"))))return;
