    var targets=new List<string>();var raw=appliedManifest.ContainsKey("targets")?appliedManifest["targets"] as System.Collections.IEnumerable:null;if(raw!=null)foreach(object value in raw){string target=Convert.ToString(value),current;desktop.GetWallpaper(target,out current);if(String.Equals(current,Get(appliedManifest,"appliedPath"),StringComparison.OrdinalIgnoreCase))targets.Add(target);}
    if(targets.Count==0){applied=false;if(File.Exists(Program.Applied))File.Delete(Program.Applied);return;}
